            c.push(m,0x1u32);
            c.set(1,32,c.get(6,32));
            c.push(m, 0x4237ff);
            { let args = [m.r32(c.r[4].wrapping_add(4)), m.r32(c.r[4].wrapping_add(8))]; c.r[0] = host.call(m, 0x4ad8d0, c.r[1], &args); }
            c.r[4] = c.r[4].wrapping_add(12);
